using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Geometry;

internal sealed class MiuraSlabIncidenceDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Geometry/MiuraSlabIncidence.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Individual extrema and maximal occupied intervals", H("Individual extrema and maximal occupied intervals"),
        Blocks(
            Describe.Lean(DescribeId.Create("miuraslabincidence-isrowslab"),
                DeclarationHandle.Create(Prefix + "IsRowSlab"), H("Actual row slabs"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A slab is a nonempty closed row interval in which every row contains an ambient extremum, and every existing immediately adjacent outside row is unoccupied. This is a maximal consecutive occupied interval of the given array."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-rowslabs"),
                DeclarationHandle.Create(Prefix + "rowSlabs"), H("All actual row slabs"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The finite set contains precisely the maximal occupied intervals of the original array."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-row-slab-unique"),
                DeclarationHandle.Create(Prefix + "row_slab_unique"), H("Slab uniqueness at a row"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Two maximal occupied intervals containing the same actual row are equal. An earlier endpoint would put the occupied predecessor of the later endpoint inside the earlier interval, contradicting maximality."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("miuraslabincidence-minrowslabs"),
                DeclarationHandle.Create(Prefix + "minRowSlabs"), H("Minimum row slabs"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("These are proper actual row slabs all of whose existing outward edges increase height by one. Proper means that at least one outward row cut exists."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-maxrowslabs"),
                DeclarationHandle.Create(Prefix + "maxRowSlabs"), H("Maximum row slabs"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("These are proper actual row slabs all of whose existing outward edges decrease height by one."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-neutralrowslabs"),
                DeclarationHandle.Create(Prefix + "neutralRowSlabs"), H("Neutral row slabs"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("These are actual row slabs internal to the grid with a common unit downward increment on the two full-width boundary cuts. Both signs are included."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-extrema"),
                DeclarationHandle.Create(Prefix + "extrema"), H("Individual extremum cells"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The finite extremum set retains each cell that is an ambient minimum or maximum. It does not identify cells with the same pair of slab endpoints."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-rowincidences"),
                DeclarationHandle.Create(Prefix + "rowIncidences"), H("Individual row incidences"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A row incidence is an individual extremum cell whose row belongs to the specified interval."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-neutral-row-degree"),
                DeclarationHandle.Create(Prefix + "neutral_row_degree"), H("Two distinct row incidences"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every actual neutral row slab of an integer unit-edge array with at least two rows contains at least two distinct extremum cells, one minimum and one maximum."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("miuraslabincidence-neutral-rows-individual-count"),
                DeclarationHandle.Create(Prefix + "neutral_rows_individual_count"), H("Disjoint neutral row counting"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every unit-edge array with at least two rows, twice the number of actual neutral row slabs is at most the number of individual extrema contained in their union. Distinct actual slabs have disjoint row sets."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("miuraslabincidence-transposeheight"),
                DeclarationHandle.Create(Prefix + "transposeHeight"), H("Transposition of the same array"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Transposition swaps the two finite coordinates and keeps the original integer height value. Column slab families are the row slab families of this transposed array."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-transpose-isheight"),
                DeclarationHandle.Create(Prefix + "transpose_isHeight"), H("Transposed unit-edge law"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Transposing an integer unit-edge height array preserves its unit-edge law."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("miuraslabincidence-neutralcolslabs"),
                DeclarationHandle.Create(Prefix + "neutralColSlabs"), H("Neutral column slabs"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The actual neutral column intervals are obtained by transposing the original array and taking its neutral row intervals."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("miuraslabincidence-neutral-col-degree"),
                DeclarationHandle.Create(Prefix + "neutral_col_degree"), H("Two distinct column incidences"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every actual neutral column slab of an integer unit-edge array with at least two rows contains at least two distinct individual extremum cells."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("miuraslabincidence-neutral-cols-individual-count"),
                DeclarationHandle.Create(Prefix + "neutral_cols_individual_count"), H("Disjoint neutral column counting"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Twice the number of actual neutral column slabs is at most the number of individual extrema in their union. The proof transports the forcing argument and preserves distinct original cells."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("miuraslabincidence-neutral-not-outward"),
                DeclarationHandle.Create(Prefix + "neutral_not_outward"), H("Neutral and nonneutral signs are incompatible"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("If an actual internal interval has equal downward cut increments, it cannot have the same nonzero outward increment on both cuts. The actual top and bottom edge equations would force that outward increment to be zero. The grid must have at least one column."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("miuraslabincidence-extrema-card-split"),
                DeclarationHandle.Create(Prefix + "extrema_card_split"), H("Exact minimum and maximum count"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every array with at least two rows, the cardinality of its individual extremum set is the sum of the exact minimum and maximum cardinalities from the residual counting definitions. A cell cannot be both kinds of extremum because it has an existing neighbour."))), DescribeRole.Theorem))));
}
